  [ [[v5748eaic9thg]] ] = { t = [[变体职业叠加与变更]], q = [[为了叠加变体职业，究竟什么算作变更了职业能力？]], a = [=[一般来说，如果某项职业能力包含多个子能力，那么选取两个只变更不同子能力的变体职业是可以的。这包括两个分别变更或替换不同[[吟游表演]]的[[吟游诗人]]变体职业（尽管吟游表演严格说来是单独一项职业能力），也包括两个分别替换不同等级所获武器训练的[[战士]]变体职业（有时称为“武器训练 I、II、III 或 IV”），尽管它们都归在武器训练这一项职业能力之下。

然而，如果某个变体职业改变了母职业能力本身的运作方式——比如哑剧演员（mime）变体职业让所有吟游表演完全无声，只有视觉成分而没有听觉成分——你就不能把它与任何变更或替换其子能力的变体职业一起选取。这甚至适用于小到“每天多1轮吟游表演”“在可选奖励专长列表里多加一个奖励专长”或“给职业增加一项本职技能”这样的改动。一如既往，GM们可以自行决定以房规按个案允许小幅重叠，但这条规则的根源在于这些改动组合起来结果无法预料。]=], book = [[进阶玩家指南]], date = [[2015/01/06]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9thg]], cat = [[FAQ]], ai = true, pages = { [[变体职业]] } },
  [ [[v5748eaic9rqp]] ] = { t = [[动物图腾萨满的自然变身]], q = [=[动物图腾萨满这些变体职业，在哪个职业等级获得[[德鲁伊#自然变身 (Wild Shape, Su)|自然变身]]？]=], a = [[德鲁伊的动物图腾萨满变体职业要到职业等级6才获得自然变身。

（本书中的其他德鲁伊变体职业用了更清楚的措辞，说明角色要到6级才获得该能力，动物图腾萨满也应当使用这种措辞。此外，修改后的自然变身职业能力描述里应当加上一句“此能力取代自然变身。”）]], book = [[进阶玩家指南]], date = [[2014/01/02]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9rqp]], cat = [[FAQ]], ai = false, pages = { [[德鲁伊]] } },
  [ [[v5748eaic9uws]] ] = { t = [[保镖与协助他人]], q = [=[[[保镖]]专长说我可以消耗我的一次[[借机攻击]]，对相邻盟友的AC进行[[协助他人]]，但它没有说这是否解除协助他人的其他限制。尤其是，我需要威胁攻击者吗？还有，该敌人是否因此对我引发了借机攻击？]=], a = [=[你仍须满足协助他人的全部要求，包括威胁攻击者。保镖会用掉你本轮的一次借机攻击，但该敌人并没有对你引发借机攻击，你也不是在进行借机攻击（这对[[双重借机]]之类的能力很重要）。]=], book = [[进阶玩家指南]], date = [[2016/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9uws]], cat = [[FAQ]], ai = true, pages = { [[保镖]] } },
  [ [[v5748eaic9ucx]] ] = { t = [[唤起死亡的尸体需求]], q = [=[唤起死亡启示说你可以唤起一个骷髅或僵尸来服侍你，这具体是什么意思？我需要尸体吗？如果不需要，我能不能想唤起什么就唤起什么，比如一只急速的[[泰拉斯奎兽]]僵尸？]=], a = [=[唤起死亡不需要尸体；你直接召来该生物（从地里升起可以作为这一效果的视觉表现）。无论哪种情况，你召来的都是《[[怪物图鉴]]》里的基础生物（人类骷髅或人类僵尸），再加上启示所给的修改（额外生命骰、急速或血腥，以及进阶模板）。由GM决定，体貌或骨骼结构明显不同的先知，可以用这一能力召来外观上更像先知本人而不是人类的骷髅和僵尸，但这不影响它们的游戏机制。]=], book = [[进阶玩家指南]], date = [[2016/01/02]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9ucx]], cat = [[FAQ]], ai = true, pages = { [[秘示域/骨骸秘示域]] } },
  [ [[v5748eaic9u3g]] ] = { t = [[“不叠加”与非加值效果]], q = [[如果一个法术说它不与另一个法术或“类似效果”叠加，而其中有些效果并不是加值，这是什么意思？]], a = [=[如果你有两个带有非加值效果的法术，且这些法术或效果被注明不叠加，意思是作用于同一规则组成部分或同一情境的效果不叠加，因此，如果它们对同一规则组成部分施加不同的非加值效果，则以最近施展的法术为准。例如，[[隼之型]]明确规定它不与任何其他扩大武器重击威胁范围的效果叠加，比如[[精通重击]]或[[锐锋]]。这意味着隼之型中作用于重击的那部分不与这些效果叠加，但这并不妨碍拥有精通重击的人获得察觉检定和攻击检定上的表现加值。如果一个拥有精通重击（轻弩）的角色施展隼之型，他的重击会从17–20/x2变为19–20/x3。同样，[[热情祝福]]不与[[加速术]]叠加，这意味着两个法术所提供的速度提升、额外攻击，以及攻击检定／AC／反射豁免加值不会叠加；但如果两个法术同时生效，你仍然可以从加速术获得这三项益处，同时选择以迅捷动作站起，或对低环法术应用超魔。]=], book = [[进阶玩家指南]], date = [[2015/01/11]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9u3g]], cat = [[FAQ]], ai = true, pages = { [[魔法]] } },
  [ [[v5748eaic9qoy]] ] = { t = [[尖笑每轮一次]], q = [[我能用标准动作和移动动作在一轮里尖笑两次，让另一项巫术延长两轮吗？]], a = [[不能，你每轮只能使用一次尖笑。

《进阶玩家指南》的后续印刷版正考虑对此加以澄清。]], book = [[进阶玩家指南]], date = [[2013/01/06]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9qoy]], cat = [[FAQ]], ai = false, pages = { [[尖笑]] } },
  [ [[v5748eaic9ngd]] ] = { t = [[尖笑与声音]], q = [[使用这项巫术时，我的角色真的必须疯狂地尖笑，还是这只是风味文字？]], a = [=[你的角色确实必须尖笑——声音大概要很响，音量和清晰度要达到类似法术的语言成分所需的程度。

2013年7月19日编辑：

如果女巫处于[[沉默术]]效果中，她就无法使用尖笑巫术。

如果目标处于沉默术效果中，则不受尖笑影响。

下次印刷《进阶玩家指南》时可能需要加上说明文字。]=], book = [[进阶玩家指南]], date = [[2013/01/06]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9ngd]], cat = [[FAQ]], ai = false, pages = { [[尖笑]] } },
  [ [[v5748eaic9ngd-2]] ] = { t = [[魔釜与调制药剂]], q = [=[一名1级就选了这项巫术的女巫，能使用[[调制药剂]]专长吗？尽管调制药剂有“施法者等级3级”的先决条件。]=], a = [[可以。]], book = [[进阶玩家指南]], date = [[2010/01/11]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9ngd]], cat = [[FAQ]], ai = false, pages = { [[魔釜]] } },
  [ [[v5748eaic9qqn]] ] = { t = [[德鲁伊伙伴与骑士坐骑叠加]], q = [=[从德鲁伊职业获得的[[动物伙伴]]等级，和骑士的坐骑等级叠加吗？]=], a = [=[如果这种动物既在骑士的坐骑列表上，又在你另一职业的动物伙伴列表上，那么你的骑士等级和德鲁伊等级叠加，用来决定该动物的能力。如果该动物不在骑士的坐骑列表上，德鲁伊等级就不叠加，你必须拥有不同的动物（一个是动物伙伴，一个是骑士坐骑）。

例如，如果你是中型体型的德鲁伊，选择了马作为伙伴，那么骑士等级会叠加，用来决定这匹马的能力。如果你是中型体型的德鲁伊，选择了鸟类伙伴，那么骑士等级不会叠加来决定这只鸟的能力，你必须再选一种生物作为你的坐骑（或者放弃那只鸟，改选一个可以当坐骑的动物伙伴）。

同样的回答也适用于骑士／[[游侠]]的兼职角色。

（请注意，设计团队不鼓励玩家同时拥有不止一个伙伴生物，因为这些生物往往比一个受益于上述叠加规则的单个生物弱得多，还会增加扮演该角色时的记录负担。）]=], book = [[进阶玩家指南]], date = [[2013/01/06]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9qqn]], cat = [[FAQ]], ai = false, pages = { [[骑士]], [[德鲁伊]] } },
  [ [[v5748eaic9ni5]] ] = { t = [[梯云纵与无限轻身坠]], q = [=[这个专长（以及[[壁虎游墙]]）与能无限距离坠落的20级武僧如何配合？]=], a = [[这两个专长都应当允许武僧移动最多50尺（若不是20级把它改成了“无限”，武僧轻身坠能力的数学进阶会是100尺，其一半就是50尺）。《进阶玩家指南》第二次印刷会反映这一信息。]], book = [[进阶玩家指南]], date = [[2010/01/11]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9ni5]], cat = [[FAQ]], ai = false, pages = { [[梯云纵]], [[壁虎游墙]] } },
  [ [[v5748eaic9nk1]] ] = { t = [[易容巫术的时限]], q = [[这项巫术的时间限制是什么？]], a = [[该巫术的描述应当写明，女巫每天可使用此能力的小时数等于女巫的职业等级。（这一点已在《进阶玩家指南》第二次印刷中加上。）]], book = [[进阶玩家指南]], date = [[2010/01/12]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9nk1]], cat = [[FAQ]], ai = false, pages = { [[易容(巫术)]] } },
  [ [[v5748eaic9raj]] ] = { t = [[鹰图腾萨满的大鹏]], q = [=[德鲁伊的[[鹰图腾萨满]]怎样才能变成[[大鹏]]？大鹏是巨型体型，而自然变身所能达到的最大体型是超大型。]=], a = [[官方Paizo产品中缺少合适的大型鸟类数据，妨碍了这个变体职业的规则选项。

为解决这个问题，鹰图腾萨满德鲁伊可以用自然变身变成一只中型体型的鹰（如同对小型鹰应用了巨化生物简易模板），也可以用自然变身变成一只超大型体型的大鹏（如同对巨型体型的大鹏应用了幼体生物简易模板）。所变之形的能力，由自然变身所对应的野兽形态法术决定，并按鹰图腾萨满的有效德鲁伊等级判定。

这一裁定只适用于鹰图腾萨满，不适用于任何其他动物图腾萨满变体职业。]], book = [[进阶玩家指南]], date = [[2013/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9raj]], cat = [[FAQ]], ai = false, pages = { [[鹰图腾萨满]] } },
  [ [[v5748eaic9o9t]] ] = { t = [[邪眼的多次使用]], q = [[我能对同一个目标多次使用这项巫术吗？]], a = [=[可以。只要你每次使用该巫术时施加的减值不同（AC、属性检定、攻击检定、豁免检定或技能检定），同一目标身上就可以同时有多项减值。对目标施加同一种减值，只会把持续时间重置为最近一次使用的时间。

例子：第1轮，你对目标的AC施放邪眼。第2轮，你对目标的攻击检定施放邪眼，于是目标身上现在有两个邪眼巫术。第3轮，你对目标的豁免检定施放邪眼，于是它身上有了三个邪眼巫术。第4轮，你再次对它的AC施放邪眼，重置AC邪眼的持续时间（这不会让它的AC再多一个-2减值）。如果有两名女巫对同一目标使用邪眼，情形也是一样——只要每个邪眼巫术作用于不同的对象，它们就全都生效。

这并不违反减值叠加的通则——每个邪眼效果基本上算是不同的来源，尽管它们都出自邪眼巫术（邪眼巫术很像五个较弱的巫术归在同一把伞下）。就像对同一目标多次施展[[降咒]]，只要它们的作用各不相同（减益力量、减益敏捷、减益攻击检定、不采取行动，等等），就应当叠加一样，多次使用邪眼巫术，只要针对的是不同的游戏数据，就可以叠加。]=], book = [[进阶玩家指南]], date = [[2011/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9o9t]], cat = [[FAQ]], ai = false, pages = { [[邪眼]] } },
  [ [[v5748eaic9nb9]] ] = { t = [[飞翔巫术只对自己生效]], q = [=[我的女巫能把她的[[羽落术]]和[[浮空术]]能力用在其他生物身上吗？]=], a = [[不能。飞翔巫术的所有方面都只影响女巫自己（不过她可以按这些法术效果所述，在自己的负重额度内携带物品或生物）。（《进阶玩家指南》第二次印刷已包含这一更新信息。）]], book = [[进阶玩家指南]], date = [[2010/01/09]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9nb9]], cat = [[FAQ]], ai = false, pages = { [[飞翔]] } },
  [ [[v5748eaic9pkc]] ] = { t = [[祈福的受益频率]], q = [[一个生物能多频繁地从这项巫术中“受益”？如果它持续不止一轮，是否第一次使用后就结束？]], a = [[当一个生物成为祈福巫术的目标时，它每轮获得一次该巫术的益处，直到巫术失效（持续时间由施放该效果的女巫等级决定）。一旦结束，该生物在24小时内不能再次成为该巫术的目标。]], book = [[进阶玩家指南]], date = [[2012/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9pkc]], cat = [[FAQ]], ai = true, pages = { [[祈福]] } },
  [ [[v5748eaic9n87]] ] = { t = [[一拥而上与远程攻击]], q = [[这个专长（第161页）能让你用远程武器夹击敌人吗？]], a = [=[一拥而上专长让你只要有两名盟友威胁你的对手，就算作在[[夹击]]。该专长没有提到包含远程攻击，而夹击明确针对的是近战攻击，因此远程攻击不受益于这个专长。（JMB，2010年8月13日）]=], book = [[进阶玩家指南]], date = [[2010/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9n87]], cat = [[FAQ]], ai = false, pages = { [[一拥而上]] } },
  [ [[v5748eaic9r7c]] ] = { t = [[半精灵／半兽人的种族选项]], q = [=[[[半精灵]]或[[半兽人]]的角色，能选择人类的种族[[天赋职业]]奖励吗？]=], a = [[可以。半精灵和半兽人可以选择种族天赋职业奖励、变体职业、背景特性等等，如同他们是两个种族的完整成员一样（半精灵可以选择精灵和人类的规则元素，半兽人可以选择人类和兽人的规则元素）。

2013年9月26日编辑：这是对先前裁定的推翻。它解决了这条FAQ、另一条《进阶玩家指南》FAQ和一条《核心规则书》FAQ之间的矛盾。]], book = [[进阶玩家指南]], date = [[2013/01/09]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9r7c]], cat = [[FAQ]], ai = false, pages = { [[半精灵]], [[半兽人]] } },
  [ [[v5748eaic9n88]] ] = { t = [[獠牙与利牙突变]], q = [=[这个替代种族特性，能和[[利牙突变]]专长（第168页）叠加，让你获得两个啮咬攻击吗？]=], a = [[这是我们试图用多种方式表达同一个想法的地方之一。就这一条来说，答案是不能，除非你想办法多长一张嘴。一般来说，每种天生武器每轮只能使用一次。这同样适用于野蛮人的野性之怒狂暴之力（《核心规则书》第32页）。]], book = [[进阶玩家指南]], date = [[2010/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9n88]], cat = [[FAQ]], ai = false, pages = { [[半兽人]], [[利牙突变]] } },
  [ [[v5748eaic9n89]] ] = { t = [[鬼扰与法术材料包]], q = [=[[[先知诅咒/鬼扰|鬼扰]]诅咒（第44页）会影响先知的法术材料包里的物品吗？]=], a = [[问题在于，鬼扰诅咒是否会导致先知在施展任何需要材料成分的法术时，必须先花一个标准动作去找出正确的材料成分。对先知们来说幸运的是，并非如此。法术材料包里的物品是模糊而没有明确定义的（有意如此，免得施法者还要记录自己带了多少蝙蝠粪），因此这个诅咒对这类成分没有影响。为了便于游戏，这一点适用于所有材料成分，包括昂贵的材料成分。]], book = [[进阶玩家指南]], date = [[2010/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9n89]], cat = [[FAQ]], ai = false, pages = { [[先知诅咒/鬼扰]] } },
}